import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import { children, splitProps } from 'solid-js';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import styles from './Table.module.css';

type TableSize = 'sm' | 'md' | 'lg';
type TableRootProps = HTMLArkProps<'table'> & {
  interactive?: boolean;
  showColumnBorder?: boolean;
  size?: TableSize;
  stickyHeader?: boolean;
  striped?: boolean;
  'data-interactive'?: string | boolean;
  'data-show-column-border'?: string | boolean;
  'data-sticky-header'?: string | boolean;
  'data-striped'?: string | boolean;
};
type TableCaptionProps = HTMLArkProps<'caption'> & {
  side?: 'top' | 'bottom';
};
type TableColumnHeaderProps = HTMLArkProps<'th'> & {
  numeric?: boolean;
  'data-numeric'?: string | boolean;
};
type TableCellProps = HTMLArkProps<'td'> & {
  numeric?: boolean;
  'data-numeric'?: string | boolean;
};
type TableEmptyProps = HTMLArkProps<'td'> & {
  colSpan: number;
};

function Table(props: TableRootProps) {
  const [local, others] = splitProps(props, [
    'class',
    'data-interactive',
    'data-show-column-border',
    'data-sticky-header',
    'data-striped',
    'interactive',
    'showColumnBorder',
    'size',
    'stickyHeader',
    'striped',
  ]);

  return (
    <ark.table
      {...others}
      data-scope="table"
      data-part="root"
      data-slot="table-root"
      data-interactive={local.interactive || undefined}
      data-show-column-border={local.showColumnBorder || undefined}
      data-size={local.size ?? 'md'}
      data-sticky-header={local.stickyHeader || undefined}
      data-striped={local.striped || undefined}
      class={clsx(styles.root, local.class)}
    />
  );
}

function TableScrollArea(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.div
      {...others}
      data-scope="table"
      data-part="scroll-area"
      data-slot="table-scroll-area"
      class={clsx(styles.scrollArea, local.class)}
    />
  );
}

function TableCaption(props: TableCaptionProps) {
  const [local, others] = splitProps(props, ['class', 'side']);

  return (
    <ark.caption
      {...others}
      data-scope="table"
      data-part="caption"
      data-side={local.side ?? 'bottom'}
      data-slot="table-caption"
      class={clsx(styles.caption, local.class)}
    />
  );
}

function TableColumnGroup(props: HTMLArkProps<'colgroup'>) {
  return (
    <ark.colgroup
      {...props}
      data-scope="table"
      data-part="column-group"
      data-slot="table-column-group"
    />
  );
}

function TableColumn(props: HTMLArkProps<'col'>) {
  return <ark.col {...props} data-scope="table" data-part="column" data-slot="table-column" />;
}

function TableHeader(props: HTMLArkProps<'thead'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.thead
      {...others}
      data-scope="table"
      data-part="header"
      data-slot="table-header"
      class={clsx(styles.header, local.class)}
    />
  );
}

function TableBody(props: HTMLArkProps<'tbody'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.tbody
      {...others}
      data-scope="table"
      data-part="body"
      data-slot="table-body"
      class={clsx(styles.body, local.class)}
    />
  );
}

function TableFooter(props: HTMLArkProps<'tfoot'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.tfoot
      {...others}
      data-scope="table"
      data-part="footer"
      data-slot="table-footer"
      class={clsx(styles.footer, local.class)}
    />
  );
}

function TableRow(props: HTMLArkProps<'tr'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.tr
      {...others}
      data-scope="table"
      data-part="row"
      data-slot="table-row"
      class={clsx(styles.row, local.class)}
    />
  );
}

function TableColumnHeader(props: TableColumnHeaderProps) {
  const [local, others] = splitProps(props, ['class', 'data-numeric', 'numeric']);

  return (
    <ark.th
      {...others}
      data-scope="table"
      data-part="column-header"
      data-numeric={local.numeric || undefined}
      data-slot="table-column-header"
      class={clsx(styles.columnHeader, local.numeric && styles.numeric, local.class)}
    />
  );
}

function TableCell(props: TableCellProps) {
  const [local, others] = splitProps(props, ['class', 'data-numeric', 'numeric']);

  return (
    <ark.td
      {...others}
      data-scope="table"
      data-part="cell"
      data-numeric={local.numeric || undefined}
      data-slot="table-cell"
      class={clsx(styles.cell, local.numeric && styles.numeric, local.class)}
    />
  );
}

function TableEmpty(props: TableEmptyProps) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <TableRow data-empty>
      <ark.td
        {...others}
        data-scope="table"
        data-part="empty"
        data-slot="table-empty"
        class={clsx(styles.cell, styles.empty, local.class)}
      >
        {resolvedChildren() ?? a11yLabels.noResults}
      </ark.td>
    </TableRow>
  );
}

export {
  Table,
  TableBody,
  TableCaption,
  TableCell,
  TableColumn,
  TableColumnGroup,
  TableColumnHeader,
  TableEmpty,
  TableFooter,
  TableHeader,
  TableRow,
  TableScrollArea,
};
export type { TableRootProps, TableSize };

@layer moduix.components {
  .scrollArea {
    box-sizing: border-box;
    position: relative;
    width: 100%;
    min-width: 0;
    overflow-x: auto;
    border: var(--moduix-border-width-sm) solid
      var(--moduix-table-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-table-bg, var(--moduix-color-card));
  }

  .root {
    --_table-cell-padding-x: var(--moduix-table-cell-padding-x, var(--moduix-spacing-4));
    --_table-cell-padding-y: var(--moduix-table-cell-padding-y, var(--moduix-spacing-3));

    width: 100%;
    border-collapse: collapse;
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    text-align: start;
    isolation: isolate;

    &[data-size='sm'] {
      --_table-cell-padding-x: var(--moduix-table-cell-padding-x, var(--moduix-spacing-3));
      --_table-cell-padding-y: var(--moduix-table-cell-padding-y, var(--moduix-spacing-2));
      font-size: var(--moduix-text-xs);
      line-height: var(--moduix-line-height-text-xs);
    }

    &[data-size='lg'] {
      --_table-cell-padding-x: var(--moduix-table-cell-padding-x, var(--moduix-spacing-5));
      --_table-cell-padding-y: var(--moduix-table-cell-padding-y, var(--moduix-spacing-4));
      font-size: var(--moduix-text-md);
      line-height: var(--moduix-line-height-text-md);
    }
  }

  .caption {
    padding-inline: var(--_table-cell-padding-x);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    text-align: start;
    text-wrap: pretty;

    &[data-side='top'] {
      caption-side: top;
      padding-block: var(--moduix-spacing-2) var(--moduix-spacing-3);
    }

    &[data-side='bottom'] {
      caption-side: bottom;
      padding-block: var(--moduix-spacing-3) var(--moduix-spacing-2);
    }
  }

  .root[data-sticky-header] .header {
    position: sticky;
    inset-block-start: 0;
    z-index: 3;
    background-color: var(--moduix-table-bg, var(--moduix-color-card));
  }

  .footer {
    border-top: var(--moduix-border-width-sm) solid
      var(--moduix-table-border-color, var(--moduix-color-border));
    background-color: var(--moduix-color-muted);
    font-weight: var(--moduix-weight-medium);
  }

  /* Sticky cells repaint the row state over their own background through --_table-row-bg. */
  .row {
    --_table-row-bg: initial;

    background-color: var(--_table-row-bg, transparent);
  }

  .header .row,
  .body .row:not(:last-child) {
    border-bottom: var(--moduix-border-width-sm) solid
      var(--moduix-table-border-color, var(--moduix-color-border));
  }

  .root[data-striped] .body .row:nth-child(even):not([data-empty]) {
    --_table-row-bg: var(
      --moduix-table-row-bg-striped,
      color-mix(in oklab, var(--moduix-color-muted) 35%, transparent)
    );
  }

  @media (hover: hover) {
    .root[data-interactive] .body .row:not([data-empty]):hover {
      --_table-row-bg: var(--moduix-table-row-bg-hover, var(--moduix-color-muted));
    }
  }

  .root[data-interactive] .body .row:not([data-empty]):focus-within {
    --_table-row-bg: var(--moduix-table-row-bg-hover, var(--moduix-color-muted));
  }

  .columnHeader,
  .cell {
    position: relative;
    z-index: 0;
    padding-block: var(--_table-cell-padding-y);
    padding-inline: var(--_table-cell-padding-x);

    &[data-sticky] {
      position: sticky;
      z-index: 2;
      background-color: var(--moduix-table-bg, var(--moduix-color-card));
      background-image: linear-gradient(var(--_table-row-bg), var(--_table-row-bg));
    }

    &[data-sticky='start'] {
      inset-inline-start: 0;
    }

    &[data-sticky='end'] {
      inset-inline-end: 0;
    }
  }

  .root[data-show-column-border] :is(.columnHeader, .cell):not(:last-child) {
    border-inline-end: var(--moduix-border-width-sm) solid
      var(--moduix-table-border-color, var(--moduix-color-border));
  }

  .columnHeader {
    color: var(--moduix-color-muted-foreground);
    font-weight: var(--moduix-weight-medium);
    text-align: inherit;
    white-space: nowrap;
  }

  .numeric {
    text-align: end;
    white-space: nowrap;
    font-variant-numeric: tabular-nums;
  }

  .empty {
    padding-block: calc(var(--_table-cell-padding-y) * 2);
    color: var(--moduix-color-muted-foreground);
    text-align: center;
  }
}
